  "decision_target": "eligibility for Gift Aid on a donation",
  "decision_unit": "one donation",
  "eligibility_expression": {
    "ref": "a1"
  },
  "limitations": [
    "The policy does not specify whether donations from individuals are eligible only if the donor is a UK resident or whether tax year boundaries apply to the tax year in which the donation is received, though the tax year is referenced in the policy.",
    "The policy does not specify whether a donation from a donor who has made other Gift Aid donations in the same year affects eligibility for this specific donation, though the tax summary and declared donations are referenced."
  ],
  "scope_issues": [
    "The policy applies to donations from individuals to charities or CASCs, but does not specify whether Gift Aid can be claimed on donations made in a single transaction or on a combination of donations from the same donor, nor whether a batch of donations from different sources must be treated separately."
  ]
